// =============================================================================
// Fapshi API client — server-side only
// =============================================================================
//
// Credentials live in Edge Function secrets and never leave the server. The
// Flutter app calls our own functions; it never sees `apiuser` / `apikey`.
//
// Endpoints and fields below follow the official documentation
// (https://docs.fapshi.com). Nothing here is invented:
//
//   POST /initiate-pay            → { message, link, transId, dateInitiated }
//   POST /direct-pay              → { message, transId, dateInitiated }
//   GET  /payment-status/{transId}→ full transaction object (also the webhook body)
//   POST /payout                  → { message, transId, dateInitiated }
//   GET  /balance                 → account balance
//
// Auth is two headers: `apiuser` and `apikey`.
//
// PROVIDER-SIDE ACTIVATION (documented, not assumed to be done):
//   * Direct Pay is disabled by default on live and must be activated by Fapshi.
//   * Payouts are disabled by default on live and must be activated by Fapshi,
//     and an activated payout service CANNOT also collect payments — so
//     collections and payouts use two different services, i.e. two credential
//     pairs. That is why this client takes the credential pair as an argument.
// =============================================================================

type FapshiEnv = "sandbox" | "live";

const FAPSHI_BASE_URLS: Record<FapshiEnv, string> = {
  sandbox: "https://sandbox.fapshi.com",
  live: "https://live.fapshi.com",
};

interface FapshiCredentials {
  apiUser: string;
  apiKey: string;
}

/** The transaction shape returned by /payment-status and posted to webhooks. */
interface FapshiTransaction {
  transId: string;
  status: "CREATED" | "PENDING" | "SUCCESSFUL" | "FAILED" | "EXPIRED";
  medium?: string;
  serviceName?: string;
  transType?: "Collection" | "Payout";
  amount?: number;
  revenue?: number;
  payerName?: string;
  email?: string;
  redirectUrl?: string;
  externalId?: string;
  userId?: string;
  webhook?: string;
  reason?: string;
  financialTransId?: string;
  dateInitiated?: string;
  dateConfirmed?: string;
}

interface FapshiInitiateResponse {
  message: string;
  link: string;
  transId: string;
  dateInitiated?: string;
}

interface FapshiTransIdResponse {
  message: string;
  transId: string;
  dateInitiated?: string;
}

class FapshiError extends Error {
  constructor(message: string, readonly status: number, readonly body: unknown) {
    super(message);
    this.name = "FapshiError";
  }
}

/** Reads the environment (sandbox by default — live is never implicit). */
function fapshiEnv(): FapshiEnv {
  return Deno.env.get("FAPSHI_ENV") === "live" ? "live" : "sandbox";
}

function collectionCredentials(): FapshiCredentials {
  const apiUser = Deno.env.get("FAPSHI_COLLECTION_API_USER") ?? "";
  const apiKey = Deno.env.get("FAPSHI_COLLECTION_API_KEY") ?? "";
  if (!apiUser || !apiKey) {
    throw new Error("Fapshi collection credentials are not configured");
  }
  return { apiUser, apiKey };
}

/**
 * Payout credentials. Fapshi requires a SEPARATE service for disbursement, so
 * these fall back to nothing rather than silently reusing the collection pair.
 */
function payoutCredentials(): FapshiCredentials {
  const apiUser = Deno.env.get("FAPSHI_PAYOUT_API_USER") ?? "";
  const apiKey = Deno.env.get("FAPSHI_PAYOUT_API_KEY") ?? "";
  if (!apiUser || !apiKey) {
    throw new Error("Fapshi payout credentials are not configured");
  }
  return { apiUser, apiKey };
}

async function call<T>(
  creds: FapshiCredentials,
  method: "GET" | "POST",
  path: string,
  body?: Record<string, unknown>,
): Promise<T> {
  const url = `${FAPSHI_BASE_URLS[fapshiEnv()]}${path}`;
  const response = await fetch(url, {
    method,
    headers: {
      "Content-Type": "application/json",
      apiuser: creds.apiUser,
      apikey: creds.apiKey,
    },
    // The docs are explicit that GET requests carry no body.
    body: method === "POST" && body ? JSON.stringify(body) : undefined,
  });

  const text = await response.text();
  let parsed: unknown = null;
  try {
    parsed = text ? JSON.parse(text) : null;
  } catch {
    parsed = text;
  }

  if (!response.ok) {
    const message =
      (parsed as { message?: string } | null)?.message ??
        `Fapshi request failed (${response.status})`;
    throw new FapshiError(message, response.status, parsed);
  }
  return parsed as T;
}

/** Hosted checkout link. Works on live without provider-side activation. */
function initiatePay(
  creds: FapshiCredentials,
  payload: {
    amount: number;
    email?: string;
    redirectUrl?: string;
    userId?: string;
    externalId?: string;
    message?: string;
  },
): Promise<FapshiInitiateResponse> {
  return call<FapshiInitiateResponse>(creds, "POST", "/initiate-pay", payload);
}

/** Push a payment prompt straight to a phone. Requires activation on live. */
function directPay(
  creds: FapshiCredentials,
  payload: {
    amount: number;
    phone: string;
    medium?: "mobile money" | "orange money";
    name?: string;
    email?: string;
    userId?: string;
    externalId?: string;
    message?: string;
  },
): Promise<FapshiTransIdResponse> {
  return call<FapshiTransIdResponse>(creds, "POST", "/direct-pay", payload);
}

/**
 * Authoritative status of a transaction. Rate limited by Fapshi to 6 requests
 * per minute per transId, so this is only called on real state questions —
 * never in a polling loop.
 */
function paymentStatus(
  creds: FapshiCredentials,
  transId: string,
): Promise<FapshiTransaction> {
  return call<FapshiTransaction>(
    creds,
    "GET",
    `/payment-status/${encodeURIComponent(transId)}`,
  );
}

/** Disbursement. Requires activation on live, on a payout-only service. */
function payout(
  creds: FapshiCredentials,
  payload: {
    amount: number;
    phone?: string;
    medium?: "mobile money" | "orange money" | "fapshi";
    name?: string;
    email?: string;
    userId?: string;
    externalId?: string;
    message?: string;
  },
): Promise<FapshiTransIdResponse> {
  return call<FapshiTransIdResponse>(creds, "POST", "/payout", payload);
}

function balance(creds: FapshiCredentials): Promise<unknown> {
  return call<unknown>(creds, "GET", "/balance");
}

/**
 * Constant-time comparison for the webhook secret, so a mismatch cannot be
 * narrowed down by timing.
 */
function secretMatches(received: string | null, expected: string): boolean {
  if (!received || !expected) return false;
  const a = new TextEncoder().encode(received);
  const b = new TextEncoder().encode(expected);
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

// ---- inlined from supabase/functions/_shared/supabase.ts --------------

// =============================================================================
// Supabase clients + shared HTTP helpers for the Camiva payment functions
// =============================================================================
//
// Two clients, used deliberately:
//
//   callerClient()  — carries the end user's JWT, so RLS and auth.uid() apply.
//                     Used for anything the user is entitled to do themselves
//                     (creating their own payment intent, requesting their own
//                     withdrawal).
//
//   serviceClient() — service role. Used ONLY to record provider-confirmed
//                     outcomes, through functions whose EXECUTE is revoked from
//                     authenticated. This is the boundary that makes it
//                     impossible for a client to forge a successful payment.
// =============================================================================


function serviceClient(): SupabaseClient {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
    { auth: { persistSession: false } },
  );
}

function callerClient(authorization: string): SupabaseClient {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    {
      auth: { persistSession: false },
      global: { headers: { Authorization: authorization } },
    },
  );
}

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

/**
 * Errors are returned as a short, user-safe message. Provider and database
 * detail is logged server-side only — it never reaches the app.
 */
function failure(error: unknown, status = 400): Response {
  const message = error instanceof Error ? error.message : String(error);
  console.error("[camiva-payments]", message);
  return json({ error: message }, status);
}

function requireAuth(req: Request): string {
  const authorization = req.headers.get("Authorization");
  if (!authorization) throw new Error("Not authenticated");
  return authorization;
}

// ---- from supabase/functions/withdrawals-request/index.ts --------------------

// =============================================================================
// withdrawals-request — teacher payout
// =============================================================================
//
//   Flutter → withdrawals-request → request_withdrawal (as the caller)
//                                 → Fapshi /payout
//                                 → attach_withdrawal_provider_ref (service role)
//
// The eligible amount is checked inside request_withdrawal(): it derives the
// balance from the ledger, takes an advisory lock so two taps cannot both pass,
// and refuses a second in-flight withdrawal. The client's number is never used
// as the destination — the payout goes to the teacher's stored payout account,
// which only they can change.
//
// The withdrawal ends this call as 'processing', never 'successful'. Only a
// confirmed payout status (webhook or verification) settles it.
//
// PROVIDER-SIDE ACTIVATION: payouts are disabled by default on live and need a
// separate, Fapshi-activated payout service. Without FAPSHI_PAYOUT_* secrets
// this function fails cleanly and the withdrawal is marked failed — it never
// pretends money moved.
// =============================================================================



Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  try {
    const authorization = requireAuth(req);
    const body = await req.json().catch(() => ({}));
    const amount = Number(body.amount ?? 0);
    if (!Number.isInteger(amount) || amount <= 0) {
      return json({ error: "Enter a valid amount" }, 400);
    }

    const caller = callerClient(authorization);
    const { data: withdrawal, error: requestError } = await caller
      .rpc("request_withdrawal", { p_amount: amount })
      .single();

    if (requestError || !withdrawal) {
      return failure(requestError ?? new Error("Could not request withdrawal"));
    }

    const service = serviceClient();

    // ---- Manual settlement -------------------------------------------------
    // Fapshi disburses only through a separate, provider-activated payout
    // service. While payout_mode is 'manual' the provider is not called at all:
    // the withdrawal stays 'requested' until an Camiva admin sends the money
    // themselves and records it. Nothing here implies money has moved.
    const { data: config } = await service
      .from("platform_fee_config")
      .select("payout_mode")
      .eq("id", 1)
      .maybeSingle();

    if (config?.payout_mode !== "provider") {
      return json({
        withdrawalId: withdrawal.id,
        status: withdrawal.status,
        amount: withdrawal.amount,
        currency: withdrawal.currency,
        settlementMode: "manual",
      });
    }

    try {
      const result = await payout(payoutCredentials(), {
        amount: withdrawal.amount,
        phone: withdrawal.payout_phone,
        medium: withdrawal.payout_medium === "orange money"
          ? "orange money"
          : "mobile money",
        userId: withdrawal.teacher_id,
        externalId: withdrawal.id,
        message: "Camiva earnings withdrawal",
      });

      const { data: updated, error: attachError } = await service
        .rpc("attach_withdrawal_provider_ref", {
          p_withdrawal_id: withdrawal.id,
          p_trans_id: result.transId,
        })
        .single();
      if (attachError) return failure(attachError, 500);

      return json({
        withdrawalId: updated.id,
        status: updated.status,
        amount: updated.amount,
        currency: updated.currency,
      });
    } catch (providerError) {
      const reason = providerError instanceof FapshiError
        ? providerError.message
        : "Payout could not be started";
      await service.rpc("fail_withdrawal", {
        p_withdrawal_id: withdrawal.id,
        p_reason: reason,
      });
      return json({
        withdrawalId: withdrawal.id,
        status: "failed",
        error: "Withdrawal could not be started. Your earnings are unchanged.",
      }, 502);
    }
  } catch (error) {
    return failure(error, 400);
  }
});
